import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.ConcurrentModificationException;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class Main {
    public static void main(String[] args) {
        ArrayList<Integer> array = new ArrayList<>(4);
        array.addAll(List.of(1, 2, 3, 4));
        System.out.println("ArrayList get(2): " + array.get(2));

        LinkedList<Integer> linked = new LinkedList<>(array);
        linked.addFirst(0);
        linked.addLast(5);
        System.out.println("LinkedList ends: " + linked.getFirst() + "/" + linked.getLast());

        ArrayDeque<Integer> deque = new ArrayDeque<>();
        deque.addFirst(1);
        deque.addLast(2);
        System.out.println("ArrayDeque order: " + deque.removeFirst() + "," + deque.removeFirst());

        boolean failFast = false;
        ArrayList<Integer> unsafe = new ArrayList<>(List.of(1, 2, 3, 4));
        try {
            for (Integer x : unsafe) {
                if (x == 2) unsafe.remove(x);
            }
        } catch (ConcurrentModificationException e) {
            failFast = true;
        }
        System.out.println("fail-fast observed: " + failFast);
        assert failFast;

        ArrayList<Integer> safe = new ArrayList<>(List.of(1, 2, 3, 4));
        safe.removeIf(x -> x % 2 == 0);
        System.out.println("after removeIf: " + safe);
        assert safe.equals(List.of(1, 3));

        CopyOnWriteArrayList<Integer> cow = new CopyOnWriteArrayList<>(List.of(1, 2));
        Iterator<Integer> snapshot = cow.iterator();
        cow.add(3);
        ArrayList<Integer> seen = new ArrayList<>();
        snapshot.forEachRemaining(seen::add);
        System.out.println("COW iterator snapshot: " + seen + ", current: " + cow);
        assert seen.equals(List.of(1, 2));
        assert cow.equals(List.of(1, 2, 3));
    }
}
